import * as React from 'react';
import { isDev } from '../utility/is-dev';
import {
  distributeFlowColumns,
  distributeFlowItems,
  getFlowFragmentState,
  validateFlowColumnLayout,
} from './flow-core';
import {
  getEffectiveScale,
  getOuterHeight,
  hashString,
  readFlowItemElements,
  readHeaderGroupHeights,
  readHeaderGroupKey,
  readHeaderGroupRepeats,
  readItemMeta,
  serializeKeepWithNext,
  type StaticFlowItemMeta,
} from './flow-measure';

export type { StaticFlowItemMeta } from './flow-measure';

export type StaticFlowItemGroup = {
  /** A stable key for the repeatable header group. */
  key: string;
  /** Repeat the group header if this group resumes on a later virtual page. */
  repeatHeader?: boolean;
};

export type StaticFlowFragmentContext<TItem = unknown> = {
  flowId: string;
  pageIndex: number;
  pageCount: number;
  itemIndex: number;
  itemKey: React.Key;
  item: TItem;
  groupKey?: string;
  isFirst: boolean;
  isLast: boolean;
  isFirstInFragment: boolean;
  isLastInFragment: boolean;
  isFirstInGroup: boolean;
  isFirstInGroupOnPage: boolean;
  /** This item is on a virtual continuation page of the Flow. */
  isContinuation: boolean;
  /** This group resumes from the preceding virtual page. */
  isGroupContinuation: boolean;
};

export type StaticFlowUnplaceableItem = {
  index: number;
  key: string;
  height: number;
  headerHeight: number;
  requiredHeight: number;
  availableHeight: number;
  /** Present when the item belongs to a FlowColumns track. */
  columnId?: string;
  groupKey?: string;
  reason: 'item-too-tall' | 'item-with-header-too-tall';
};

export type StaticFlowUnplaceableContext = {
  flowId: string;
  pageIndex: number;
  pageCount: number;
};

export type StaticFlowGroupHeaderFragment = {
  groupKey: string;
  itemIndex: number;
  isContinuation: boolean;
};

export type StaticFlowChunk = {
  /** Flattened visual reading order for this page; `layout` preserves parallel track identity. */
  indexes: number[];
  keys: string[];
  /** Track-local source predecessor for the first item in this continuation fragment. */
  previousSourceIndex?: number;
  /** Header insertion points for this exact measured virtual-page fragment. */
  groupHeaders?: StaticFlowGroupHeaderFragment[];
  /** A finite, renderable error page for a row that cannot fit on an empty page. */
  unplaceable?: StaticFlowUnplaceableItem;
  /** Authoritative one-level sequential/parallel fragment plan for FlowColumns. */
  layout?: StaticFlowLayoutFragment[];
};

export type StaticFlowColumn = {
  id: string;
  indexes: number[];
};

export type StaticFlowLayoutNode =
  | { kind: 'item'; index: number }
  | { kind: 'columns'; id: string; columns: StaticFlowColumn[] };

export type StaticFlowColumnFragment = {
  id: string;
  chunk: StaticFlowChunk;
};

export type StaticFlowLayoutFragment =
  | { kind: 'items'; chunk: StaticFlowChunk }
  | { kind: 'columns'; id: string; columns: StaticFlowColumnFragment[] };

type StaticFlowPlanInput = {
  heights?: number[];
  keys?: string[];
  metas?: StaticFlowItemMeta[];
  availableHeight?: number;
  headerGroupKeys?: Array<string | undefined>;
  headerGroupHeights?: Record<string, number>;
  headerGroupRepeats?: Record<string, boolean>;
  columnHeaderGroupHeights?: Record<string, Record<string, Record<string, number>>>;
  columnHeaderGroupRepeats?: Record<string, Record<string, Record<string, boolean>>>;
  onUnplaceableItem?: (item: StaticFlowUnplaceableItem) => void;
};

const planFlowChunks = distributeFlowItems as (
  input?: StaticFlowPlanInput
) => StaticFlowChunk[];
const planFlowColumnChunks = distributeFlowColumns as (
  input: StaticFlowPlanInput & { nodes: StaticFlowLayoutNode[] }
) => StaticFlowChunk[];

export type StaticFlowMeasurement = {
  flowId: string;
  chunks: StaticFlowChunk[];
  signature: string;
  unplaceableItems?: StaticFlowUnplaceableItem[];
};

export type StaticFlowContextValue = {
  mode: 'measure' | 'visible';
  pageIndex: number;
  measurementVersion?: string;
  chunksByFlowId?: Record<string, StaticFlowChunk[]>;
  registerMeasurement?: (measurement: StaticFlowMeasurement) => void;
};

export const StaticFlowContext = React.createContext<StaticFlowContextValue | null>(null);

type FlowAreaProps = {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  /** Receives the same measured plan that drives virtual continuation pages. */
  onFlowMeasurement?: (measurement: StaticFlowMeasurement) => void;
};

const useIsoLayoutEffect = typeof window === 'undefined' ? React.useEffect : React.useLayoutEffect;
const warnedMetaDefaultsWithoutType = new Set<string>();

type FlowItemType<TItem> = TItem extends { type?: infer TType }
  ? Extract<TType, string>
  : string;

type DefaultFlowItemType<TItem> = [FlowItemType<TItem>] extends [never]
  ? string
  : FlowItemType<TItem>;

function getItemType(item: unknown): string | undefined {
  if (!item || typeof item !== 'object' || !('type' in item)) return undefined;
  const type = (item as { type?: unknown }).type;
  return typeof type === 'string' || typeof type === 'number' ? String(type) : undefined;
}

function mergeItemMeta(
  base: StaticFlowItemMeta | undefined,
  override: StaticFlowItemMeta | undefined
): StaticFlowItemMeta {
  const merged: StaticFlowItemMeta = { ...(base ?? {}) };

  for (const [key, value] of Object.entries(override ?? {})) {
    if (value !== undefined) {
      (merged as Record<string, unknown>)[key] = value;
    }
  }

  return merged;
}

function numericStyle(value: string) {
  return Number.parseFloat(value || '0') || 0;
}

function assertSupportedFlowColumnGeometry(flow: HTMLElement, scale: number) {
  const verticalBox = (element: HTMLElement) => {
    const style = window.getComputedStyle(element);
    return numericStyle(style.paddingTop) +
      numericStyle(style.paddingBottom) +
      numericStyle(style.borderTopWidth) +
      numericStyle(style.borderBottomWidth);
  };
  for (const group of Array.from(
    flow.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-layout-node="columns"]')
  )) {
    const groupStyle = window.getComputedStyle(group);
    const groupVerticalMargins =
      numericStyle(groupStyle.marginTop) + numericStyle(groupStyle.marginBottom);
    if (verticalBox(group) > 0.01 || groupVerticalMargins > 0.01) {
      throw new TypeError(
        '[uhuu-components] Static.FlowColumns group vertical margin, padding, and borders are unsupported; ' +
        'put measured vertical spacing on items with getColumnItemProps.'
      );
    }
    const naturalColumnHeights: number[] = [];
    for (const column of Array.from(
      group.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-column]')
    )) {
      const style = window.getComputedStyle(column);
      const verticalMargins = numericStyle(style.marginTop) + numericStyle(style.marginBottom);
      if (
        verticalBox(column) > 0.01 ||
        verticalMargins > 0.01 ||
        numericStyle(style.rowGap) > 0.01 ||
        numericStyle(style.minHeight) > 0.01 ||
        style.maxHeight !== 'none'
      ) {
        throw new TypeError(
          '[uhuu-components] Static.FlowColumns column vertical margin, padding, borders, min/max height, and row-gap are unsupported; ' +
          'put measured vertical spacing on items with getColumnItemProps.'
        );
      }
      const naturalHeight = Array.from(
        column.querySelectorAll<HTMLElement>(
          '[data-uhuu-flow-item="true"], [data-uhuu-flow-group-header="true"]'
        )
      ).reduce((sum, child) => sum + getOuterHeight(child, scale), 0);
      naturalColumnHeights.push(naturalHeight);
    }
    const naturalGroupHeight = Math.max(0, ...naturalColumnHeights);
    if (getOuterHeight(group, scale) > naturalGroupHeight + 1) {
      throw new TypeError(
        '[uhuu-components] Static.FlowColumns group/column fixed height or wrapping adds unmeasured vertical extent.'
      );
    }
  }
}

type BuildChunksOptions = {
  onZeroHeight?: () => void;
  onUnplaceableItem?: (item: StaticFlowUnplaceableItem) => void;
};

function buildChunks(
  area: HTMLElement,
  flow: HTMLElement,
  options: BuildChunksOptions = {}
): StaticFlowMeasurement | null {
  const flowId = flow.dataset.uhuuFlowId;
  if (!flowId) return null;

  if (flow.dataset.uhuuFlowLayout === 'columns') {
    return buildFlowColumnChunks(area, flow, options);
  }

  const itemElements = readFlowItemElements(flow);
  if (!itemElements.length) {
    return {
      flowId,
      chunks: [{ indexes: [], keys: [] }],
      signature: `${flowId}:empty`,
      unplaceableItems: [],
    };
  }

  const areaRect = area.getBoundingClientRect();
  // Normalize every rect read back to layout space so a scaled preview (fit-to-pane, host zoom)
  // measures the exact same chunk plan as the unscaled published document.
  const scale = getEffectiveScale(area);
  const measuredAvailableHeight = areaRect.height ? areaRect.height / scale : area.clientHeight;
  const hasAvailableHeight = Number.isFinite(measuredAvailableHeight) && measuredAvailableHeight > 0;
  const heights = itemElements.map((item) => getOuterHeight(item, scale));
  const metas = itemElements.map(readItemMeta);
  const keys = itemElements.map((item, index) => item.dataset.uhuuFlowKey || String(index));
  const headerGroupKeys = itemElements.map(readHeaderGroupKey);
  const headerGroupRepeats = readHeaderGroupRepeats(itemElements);
  const headerGroupHeights = readHeaderGroupHeights(flow, scale);
  const unplaceableItems: StaticFlowUnplaceableItem[] = [];
  const fallbackHeight = hasAvailableHeight
    ? measuredAvailableHeight
    : heights.reduce((sum, height) => sum + height, 0) +
      Object.values(headerGroupHeights).reduce((sum, height) => sum + height, 0);

  if (!hasAvailableHeight) {
    options.onZeroHeight?.();
  }

  const finalChunks = planFlowChunks({
    heights,
    keys,
    metas,
    availableHeight: fallbackHeight,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    onUnplaceableItem: (item: StaticFlowUnplaceableItem) => {
      unplaceableItems.push(item);
      options.onUnplaceableItem?.(item);
    },
  });
  const signature = hashString(JSON.stringify({
    version: 2,
    flowId,
    availableHeight: Math.round(fallbackHeight * 100) / 100,
    heights: heights.map((height) => Math.round(height * 100) / 100),
    keys,
    metas,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    unplaceableItems,
  }));

  return { flowId, chunks: finalChunks, signature, unplaceableItems };
}

function buildFlowColumnChunks(
  area: HTMLElement,
  flow: HTMLElement,
  options: BuildChunksOptions = {}
): StaticFlowMeasurement | null {
  const flowId = flow.dataset.uhuuFlowId;
  if (!flowId) return null;
  const itemElements = readFlowItemElements(flow);
  if (!itemElements.length) {
    return {
      flowId,
      chunks: [{ indexes: [], keys: [], layout: [] }],
      signature: `${flowId}:columns:empty`,
      unplaceableItems: [],
    };
  }

  const areaRect = area.getBoundingClientRect();
  const scale = getEffectiveScale(area);
  assertSupportedFlowColumnGeometry(flow, scale);
  const measuredAvailableHeight = areaRect.height ? areaRect.height / scale : area.clientHeight;
  const hasAvailableHeight = Number.isFinite(measuredAvailableHeight) && measuredAvailableHeight > 0;
  const highestIndex = Math.max(
    -1,
    ...itemElements.map((item) => Number.parseInt(item.dataset.uhuuFlowIndex ?? '-1', 10))
  );
  const heights = Array.from({ length: highestIndex + 1 }, () => 0);
  const keys = Array.from({ length: highestIndex + 1 }, (_, index) => String(index));
  const metas = Array.from({ length: highestIndex + 1 }, () => ({} as StaticFlowItemMeta));
  const headerGroupKeys = Array.from(
    { length: highestIndex + 1 },
    () => undefined as string | undefined
  );
  for (const item of itemElements) {
    const index = Number.parseInt(item.dataset.uhuuFlowIndex ?? '-1', 10);
    if (!Number.isInteger(index) || index < 0) continue;
    heights[index] = getOuterHeight(item, scale);
    keys[index] = item.dataset.uhuuFlowKey || String(index);
    metas[index] = readItemMeta(item);
    headerGroupKeys[index] = readHeaderGroupKey(item);
  }
  const nodes = Array.from(flow.children).flatMap((node): StaticFlowLayoutNode[] => {
    if (!(node instanceof HTMLElement)) return [];
    if (node.dataset.uhuuFlowLayoutNode === 'item') {
      const item = node.matches('[data-uhuu-flow-item="true"]')
        ? node
        : node.querySelector<HTMLElement>('[data-uhuu-flow-item="true"]');
      const index = Number.parseInt(item?.dataset.uhuuFlowIndex ?? '-1', 10);
      return Number.isInteger(index) && index >= 0 ? [{ kind: 'item', index }] : [];
    }
    if (node.dataset.uhuuFlowLayoutNode !== 'columns') return [];
    const columns = Array.from(
      node.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-column]')
    ).flatMap((column): StaticFlowColumn[] => {
      const id = column.dataset.uhuuFlowColumn;
      if (!id) return [];
      const indexes = Array.from(
        column.querySelectorAll<HTMLElement>('[data-uhuu-flow-item="true"]')
      ).map((item) => Number.parseInt(item.dataset.uhuuFlowIndex ?? '-1', 10))
        .filter((index) => Number.isInteger(index) && index >= 0);
      return [{ id, indexes }];
    });
    return columns.length
      ? [{ kind: 'columns', id: node.dataset.uhuuFlowLayoutId || 'columns', columns }]
      : [];
  });
  const headerGroupRepeats = readHeaderGroupRepeats(itemElements);
  const headerGroupHeights = readHeaderGroupHeights(flow, scale);
  const columnHeaderGroupHeights: Record<string, Record<string, Record<string, number>>> = {};
  const columnHeaderGroupRepeats: Record<string, Record<string, Record<string, boolean>>> = {};
  for (const group of Array.from(
    flow.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-layout-node="columns"]')
  )) {
    const groupId = group.dataset.uhuuFlowLayoutId;
    if (!groupId) continue;
    columnHeaderGroupHeights[groupId] = {};
    columnHeaderGroupRepeats[groupId] = {};
    for (const column of Array.from(
      group.querySelectorAll<HTMLElement>(':scope > [data-uhuu-flow-column]')
    )) {
      const columnId = column.dataset.uhuuFlowColumn;
      if (!columnId) continue;
      const columnItems = Array.from(
        column.querySelectorAll<HTMLElement>('[data-uhuu-flow-item="true"]')
      );
      columnHeaderGroupHeights[groupId][columnId] = readHeaderGroupHeights(column, scale);
      columnHeaderGroupRepeats[groupId][columnId] = readHeaderGroupRepeats(columnItems);
    }
  }
  const unplaceableItems: StaticFlowUnplaceableItem[] = [];
  const fallbackHeight = hasAvailableHeight
    ? measuredAvailableHeight
    : heights.reduce((sum, height) => sum + height, 0) +
      Object.values(headerGroupHeights).reduce((sum, height) => sum + height, 0);
  if (!hasAvailableHeight) options.onZeroHeight?.();

  const chunks = planFlowColumnChunks({
    nodes,
    heights,
    keys,
    metas,
    availableHeight: fallbackHeight,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    columnHeaderGroupHeights,
    columnHeaderGroupRepeats,
    onUnplaceableItem: (item: StaticFlowUnplaceableItem) => {
      unplaceableItems.push(item);
      options.onUnplaceableItem?.(item);
    },
  });
  const signature = hashString(JSON.stringify({
    version: 3,
    flowId,
    availableHeight: Math.round(fallbackHeight * 100) / 100,
    nodes,
    heights: heights.map((height) => Math.round(height * 100) / 100),
    keys,
    metas,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    columnHeaderGroupHeights,
    columnHeaderGroupRepeats,
    unplaceableItems,
  }));
  return { flowId, chunks, signature, unplaceableItems };
}

export function FlowArea({
  children,
  className = '',
  style,
  onFlowMeasurement,
}: FlowAreaProps) {
  const context = React.useContext(StaticFlowContext);
  const areaRef = React.useRef<HTMLDivElement>(null);
  const lastSignatureRef = React.useRef<string>('');
  const warnedMultipleFlowsRef = React.useRef(false);
  const warnedZeroHeightRef = React.useRef(false);
  const warnedUnplaceableItemsRef = React.useRef(new Set<string>());

  useIsoLayoutEffect(() => {
    if (context?.mode !== 'measure' || !context.registerMeasurement || !areaRef.current) {
      return;
    }

    const area = areaRef.current;
    let rafId: number | null = null;
    let resizeObserver: ResizeObserver | null = null;
    lastSignatureRef.current = '';

    const observedMeasurementElements = new Set<HTMLElement>();
    const observeMeasurementElements = () => {
      if (!resizeObserver) return;

      for (const element of Array.from(observedMeasurementElements)) {
        if (!area.contains(element)) {
          resizeObserver.unobserve(element);
          observedMeasurementElements.delete(element);
        }
      }

      area
        .querySelectorAll<HTMLElement>(
          '[data-uhuu-flow-item="true"], [data-uhuu-flow-group-header="true"]'
        )
        .forEach((element) => {
          if (observedMeasurementElements.has(element)) return;
          observedMeasurementElements.add(element);
          resizeObserver?.observe(element);
        });
    };

    function measure() {
      observeMeasurementElements();

      const flows = area.querySelectorAll<HTMLElement>('[data-uhuu-flow="true"]');
      if (flows.length > 1 && !warnedMultipleFlowsRef.current && isDev()) {
        warnedMultipleFlowsRef.current = true;
        console.warn(
          '[uhuu-components] Static.FlowArea supports one Static.Flow child. ' +
          'Additional Static.Flow elements in the same area are ignored. Use one FlowArea per flow region.'
        );
      }

      const flow = flows[0];
      if (!flow) return;

      const measurement = buildChunks(area, flow, {
        onZeroHeight: () => {
          if (warnedZeroHeightRef.current || !isDev()) return;
          warnedZeroHeightRef.current = true;
          console.warn(
            '[uhuu-components] Static.FlowArea has flow items but no measurable height. ' +
            'Give the area an explicit height or use a constrained flex layout such as flex-1 min-h-0.'
          );
        },
        onUnplaceableItem: (item) => {
          if (warnedUnplaceableItemsRef.current.has(item.key) || !isDev()) return;
          warnedUnplaceableItemsRef.current.add(item.key);
          console.warn(
            `[uhuu-components] Static.Flow item "${item.key}" cannot fit in its FlowArea ` +
            `(${Math.round(item.requiredHeight)}px required > ${Math.round(item.availableHeight)}px available). ` +
            'It is rendered as a controlled flow error instead of clipped content.'
          );
        },
      });
      if (!measurement || measurement.signature === lastSignatureRef.current) return;

      lastSignatureRef.current = measurement.signature;
      onFlowMeasurement?.(measurement);
      context?.registerMeasurement?.(measurement);
    }

    const scheduleMeasure = () => {
      // Coalesce all observer notifications arriving in one frame. Unlike
      // cancelling and re-queuing, this cannot postpone a remeasure forever
      // while an editable surface is continuously mutating.
      if (rafId !== null) return;
      rafId = window.requestAnimationFrame(() => {
        rafId = null;
        measure();
      });
    };

    resizeObserver = new ResizeObserver(scheduleMeasure);
    resizeObserver.observe(area);
    observeMeasurementElements();
    scheduleMeasure();

    const mutationObserver = new MutationObserver(() => {
      // Reconcile new/removed measured elements in the scheduled pass rather
      // than scanning the complete flow both here and again in `measure`.
      scheduleMeasure();
    });
    mutationObserver.observe(area, {
      attributes: true,
      attributeFilter: [
        'class',
        'style',
        'data-uhuu-flow',
        'data-uhuu-flow-id',
        'data-uhuu-flow-item',
        'data-uhuu-flow-key',
        'data-uhuu-flow-break-before',
        'data-uhuu-flow-break-after',
        'data-uhuu-flow-keep-with-next',
        'data-uhuu-flow-avoid-break-inside',
        'data-uhuu-flow-group-key',
        'data-uhuu-flow-header-group-key',
        'data-uhuu-flow-header-repeat',
        'data-uhuu-flow-group-header',
      ],
      characterData: true,
      childList: true,
      subtree: true,
    });

    return () => {
      if (rafId !== null) window.cancelAnimationFrame(rafId);
      resizeObserver?.disconnect();
      mutationObserver.disconnect();
    };
  }, [context, onFlowMeasurement]);

  return (
    <div ref={areaRef} className={className} style={style} data-uhuu-flow-area="true">
      {children}
    </div>
  );
}

type FlowPageProps = {
  children: React.ReactNode;
  header?: React.ReactNode;
  footer?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  flowAreaClassName?: string;
  flowAreaStyle?: React.CSSProperties;
  onFlowMeasurement?: (measurement: StaticFlowMeasurement) => void;
};

export function FlowPage({
  children,
  header,
  footer,
  className = '',
  style,
  flowAreaClassName = '',
  flowAreaStyle,
  onFlowMeasurement,
}: FlowPageProps) {
  return (
    <div
      className={`h-full w-full flex flex-col ${className}`}
      style={style}
      data-uhuu-flow-page="true"
    >
      {header}
      <FlowArea
        className={`flex-1 min-h-0 ${flowAreaClassName}`}
        style={flowAreaStyle}
        onFlowMeasurement={onFlowMeasurement}
      >
        {children}
      </FlowArea>
      {footer}
    </div>
  );
}

function normalizeItemGroup(
  value: StaticFlowItemGroup | string | null | undefined
): StaticFlowItemGroup | undefined {
  if (typeof value === 'string') {
    return value ? { key: value, repeatHeader: true } : undefined;
  }

  if (!value?.key) return undefined;
  return {
    key: value.key,
    repeatHeader: value.repeatHeader !== false,
  };
}

/**
 * `getFlowFragmentState` resolves the fragment position with `indexOf`. The
 * renderer already walks every visible index, so prepare the same first-match
 * lookup once instead. Keeping the first position deliberately preserves the
 * core helper's behavior for a stale chunk that happens to contain an index
 * more than once.
 */
function getFirstFragmentPositions(fragmentIndexes: readonly number[]): Map<number, number> {
  const positions = new Map<number, number>();
  fragmentIndexes.forEach((itemIndex, position) => {
    if (!positions.has(itemIndex)) positions.set(itemIndex, position);
  });
  return positions;
}

/**
 * A planned header list is authoritative when it exists, including an empty
 * list. Index it once so a page with many groups does not scan it per item.
 */
function getPlannedGroupHeadersByItemIndex(
  groupHeaders: StaticFlowGroupHeaderFragment[] | undefined
): Map<number, Set<string>> | undefined {
  if (!groupHeaders) return undefined;

  const headersByItemIndex = new Map<number, Set<string>>();
  for (const header of groupHeaders) {
    let groupKeys = headersByItemIndex.get(header.itemIndex);
    if (!groupKeys) {
      groupKeys = new Set<string>();
      headersByItemIndex.set(header.itemIndex, groupKeys);
    }
    groupKeys.add(header.groupKey);
  }
  return headersByItemIndex;
}

type FlowProps<TItem, TType extends string = DefaultFlowItemType<TItem>> = {
  id: string;
  items: TItem[];
  getKey: (item: TItem, index: number) => React.Key;
  /** The third argument describes this item's visible virtual-page fragment. */
  renderItem: (
    item: TItem,
    index: number,
    fragment: StaticFlowFragmentContext<TItem>
  ) => React.ReactNode;
  getItemMeta?: (item: TItem, index: number) => StaticFlowItemMeta | undefined;
  metaDefaults?: Partial<Record<TType, StaticFlowItemMeta>>;
  getItemType?: (item: TItem, index: number) => TType | undefined;
  /** Opt into a separately measured, repeatable group header. */
  getItemGroup?: (
    item: TItem,
    index: number
  ) => StaticFlowItemGroup | string | null | undefined;
  renderGroupHeader?: (
    group: StaticFlowItemGroup,
    fragment: StaticFlowFragmentContext<TItem>
  ) => React.ReactNode;
  className?: string;
  itemClassName?: string | ((item: TItem, index: number) => string | undefined);
  groupHeaderClassName?: string | ((
    group: StaticFlowItemGroup,
    fragment: StaticFlowFragmentContext<TItem>
  ) => string | undefined);
  renderUnplaceableItem?: (
    item: StaticFlowUnplaceableItem,
    context: StaticFlowUnplaceableContext
  ) => React.ReactNode;
};

export type StaticFlowColumnsRenderContext = {
  /** Stable identity only: column geometry callbacks must return the same layout on every page. */
  flowId: string;
};

export type StaticFlowColumnsContainerProps = {
  className?: string;
  style?: React.CSSProperties;
};

type FlowColumnsProps<TItem, TType extends string = DefaultFlowItemType<TItem>> =
  FlowProps<TItem, TType> & {
    /** One-level story layout. Recursive columns are intentionally unsupported. */
    layout: StaticFlowLayoutNode[];
    getColumnGroupProps?: (
      node: Extract<StaticFlowLayoutNode, { kind: 'columns' }>,
      context: StaticFlowColumnsRenderContext
    ) => StaticFlowColumnsContainerProps | undefined;
    getColumnProps?: (
      node: Extract<StaticFlowLayoutNode, { kind: 'columns' }>,
      column: StaticFlowColumn,
      context: StaticFlowColumnsRenderContext
    ) => StaticFlowColumnsContainerProps | undefined;
    getColumnItemProps?: (
      node: Extract<StaticFlowLayoutNode, { kind: 'columns' }>,
      column: StaticFlowColumn,
      itemIndex: number,
      context: StaticFlowColumnsRenderContext
    ) => StaticFlowColumnsContainerProps | undefined;
  };

export function Flow<TItem, TType extends string = DefaultFlowItemType<TItem>>({
  id,
  items,
  getKey,
  renderItem,
  getItemMeta,
  metaDefaults,
  getItemType: resolveItemType,
  getItemGroup,
  renderGroupHeader,
  className = '',
  itemClassName,
  groupHeaderClassName,
  renderUnplaceableItem,
}: FlowProps<TItem, TType>) {
  const context = React.useContext(StaticFlowContext);
  const chunks = context?.chunksByFlowId?.[id];
  const activeChunk = context?.mode === 'visible' && chunks
    ? chunks[context.pageIndex]
    : undefined;
  const rawVisibleIndexes =
    context?.mode === 'visible' && chunks
      ? (activeChunk?.indexes ?? [])
      : context?.mode === 'visible' && context.pageIndex > 0
        ? []
        : items.map((_, index) => index);

  // Guard against stale chunk indexes when items shrink (e.g. rowCount decreased before remeasure)
  const visibleIndexes = rawVisibleIndexes.filter((idx) => (
    Number.isInteger(idx) && idx >= 0 && idx < items.length
  ));
  const itemGroups = items.map((item, index) => normalizeItemGroup(getItemGroup?.(item, index)));
  const groupKeys = itemGroups.map((group) => group?.key);
  const fragmentPositions = getFirstFragmentPositions(visibleIndexes);
  const plannedGroupHeaders = renderGroupHeader
    ? getPlannedGroupHeadersByItemIndex(activeChunk?.groupHeaders)
    : undefined;
  const pageIndex = context?.mode === 'visible' ? context.pageIndex : 0;
  const pageCount = context?.mode === 'visible' && chunks ? chunks.length : 1;

  React.useEffect(() => {
    if (!isDev() || !metaDefaults || !Object.keys(metaDefaults).length || !items.length) {
      return;
    }

    const warningKey = `${id}:${Object.keys(metaDefaults).join('|')}`;
    if (warnedMetaDefaultsWithoutType.has(warningKey)) return;

    const hasResolvableType = items.some((item, index) => (
      Boolean(resolveItemType?.(item, index) ?? getItemType(item))
    ));
    if (hasResolvableType) return;

    warnedMetaDefaultsWithoutType.add(warningKey);
    console.warn(
      `[uhuu-components] Static.Flow "${id}" received metaDefaults, but no item type could be resolved. ` +
      'Add a type field to each item or pass getItemType so defaults can be applied.'
    );
  }, [id, items, metaDefaults, resolveItemType]);

  return (
    <div
      className={className}
      data-uhuu-flow="true"
      data-uhuu-flow-id={id}
    >
      {activeChunk?.unplaceable && (
        renderUnplaceableItem?.(activeChunk.unplaceable, { flowId: id, pageIndex, pageCount }) ?? (
          <div
            role="alert"
            className="uhuu-flow-unplaceable"
            data-uhuu-flow-unplaceable="true"
            data-uhuu-flow-unplaceable-key={activeChunk.unplaceable.key}
          >
            Unable to fit “{activeChunk.unplaceable.key}” on a page. Reduce its height or split it.
          </div>
        )
      )}
      {visibleIndexes.map((itemIndex) => {
        const item = items[itemIndex];
        if (item === undefined) return null;

        const key = getKey(item, itemIndex);
        const group = itemGroups[itemIndex];
        const coreFragment = getFlowFragmentState({
          itemIndex,
          fragmentIndexes: visibleIndexes,
          fragmentIndex: fragmentPositions.get(itemIndex) ?? -1,
          groupKeys,
          pageIndex,
          pageCount,
          itemCount: items.length,
        });
        const fragment: StaticFlowFragmentContext<TItem> = {
          ...coreFragment,
          flowId: id,
          itemKey: key,
          item,
        };
        const type = resolveItemType?.(item, itemIndex) ?? (getItemType(item) as TType | undefined);
        const meta = mergeItemMeta(
          type ? metaDefaults?.[type] : undefined,
          getItemMeta?.(item, itemIndex)
        );
        const resolvedItemClassName =
          typeof itemClassName === 'function'
            ? itemClassName(item, itemIndex)
            : itemClassName;
        const hasPlannedGroupHeader = Boolean(
          group && plannedGroupHeaders?.get(itemIndex)?.has(group.key)
        );
        const shouldRenderGroupHeader = Boolean(
          group &&
          renderGroupHeader &&
          (
            hasPlannedGroupHeader || (
              !plannedGroupHeaders &&
              fragment.isFirstInGroupOnPage &&
              (fragment.isFirstInGroup || group.repeatHeader !== false)
            )
          )
        );
        const resolvedGroupHeaderClassName: string | undefined =
          typeof groupHeaderClassName === 'function'
            ? (group ? groupHeaderClassName(group, fragment) : undefined)
            : groupHeaderClassName;

        return (
          <React.Fragment key={key}>
            {shouldRenderGroupHeader && group && (
              <div
                className={resolvedGroupHeaderClassName}
                style={{ display: 'flow-root' }}
                data-uhuu-flow-group-header="true"
                data-uhuu-flow-header-group-key={group.key}
              >
                {renderGroupHeader?.(group, fragment)}
              </div>
            )}
            <div
              className={resolvedItemClassName}
              style={{ display: 'flow-root' }}
              data-uhuu-flow-item="true"
              data-uhuu-flow-key={String(key)}
              data-uhuu-flow-index={itemIndex}
              data-uhuu-flow-break-before={meta.breakBefore ? 'true' : undefined}
              data-uhuu-flow-break-after={meta.breakAfter ? 'true' : undefined}
              data-uhuu-flow-keep-with-next={serializeKeepWithNext(meta.keepWithNext)}
              data-uhuu-flow-avoid-break-inside={meta.avoidBreakInside ? 'true' : undefined}
              data-uhuu-flow-group-key={meta.groupKey}
              data-uhuu-flow-header-group-key={group?.key}
              data-uhuu-flow-header-repeat={group ? (group.repeatHeader === false ? 'false' : 'true') : undefined}
            >
              {renderItem(item, itemIndex, fragment)}
            </div>
          </React.Fragment>
        );
      })}
    </div>
  );
}

export function FlowColumns<TItem, TType extends string = DefaultFlowItemType<TItem>>({
  id,
  items,
  layout,
  getKey,
  renderItem,
  getItemMeta,
  metaDefaults,
  getItemType: resolveItemType,
  getItemGroup,
  renderGroupHeader,
  className = '',
  itemClassName,
  groupHeaderClassName,
  renderUnplaceableItem,
  getColumnGroupProps,
  getColumnProps,
  getColumnItemProps,
}: FlowColumnsProps<TItem, TType>) {
  validateFlowColumnLayout({ nodes: layout, itemCount: items.length });
  const context = React.useContext(StaticFlowContext);
  const chunks = context?.chunksByFlowId?.[id];
  const activeChunk = context?.mode === 'visible' && chunks
    ? chunks[context.pageIndex]
    : undefined;
  const isMeasurement = context?.mode !== 'visible';
  const pageIndex = context?.mode === 'visible' ? context.pageIndex : 0;
  const pageCount = context?.mode === 'visible' && chunks ? chunks.length : 1;
  const itemGroups = items.map((item, index) => normalizeItemGroup(getItemGroup?.(item, index)));
  const groupKeys = itemGroups.map((entry) => entry?.key);
  const columnsContext: StaticFlowColumnsRenderContext = {
    flowId: id,
  };

  React.useEffect(() => {
    if (!isDev() || !metaDefaults || !Object.keys(metaDefaults).length || !items.length) {
      return;
    }

    const warningKey = `${id}:columns:${Object.keys(metaDefaults).join('|')}`;
    if (warnedMetaDefaultsWithoutType.has(warningKey)) return;
    const hasResolvableType = items.some((item, index) => (
      Boolean(resolveItemType?.(item, index) ?? getItemType(item))
    ));
    if (hasResolvableType) return;

    warnedMetaDefaultsWithoutType.add(warningKey);
    console.warn(
      `[uhuu-components] Static.FlowColumns "${id}" received metaDefaults, but no item type could be resolved. ` +
      'Add a type field to each item or pass getItemType so defaults can be applied.'
    );
  }, [id, items, metaDefaults, resolveItemType]);

  const renderUnplaceable = (
    unplaceable: StaticFlowUnplaceableItem | undefined
  ): React.ReactNode => {
    if (!unplaceable) return null;
    return renderUnplaceableItem?.(unplaceable, { flowId: id, pageIndex, pageCount }) ?? (
      <div
        role="alert"
        className="uhuu-flow-unplaceable"
        data-uhuu-flow-unplaceable="true"
        data-uhuu-flow-unplaceable-key={unplaceable.key}
        data-uhuu-flow-column-id={unplaceable.columnId}
      >
        Unable to fit “{unplaceable.key}” on a page. Reduce its height or split it.
      </div>
    );
  };

  const renderIndexes = (
    rawIndexes: number[],
    plannedChunk?: StaticFlowChunk,
    resolveContainerProps?: (itemIndex: number) => StaticFlowColumnsContainerProps | undefined,
    markAsLayoutNode = false,
    sourceTrackIndexes?: number[]
  ): React.ReactNode[] => {
    const visibleIndexes = rawIndexes.filter((itemIndex) => (
      Number.isInteger(itemIndex) && itemIndex >= 0 && itemIndex < items.length
    ));
    const fragmentPositions = getFirstFragmentPositions(visibleIndexes);
    const sourceTrackPositions = sourceTrackIndexes
      ? getFirstFragmentPositions(sourceTrackIndexes)
      : undefined;
    const plannedGroupHeaders = renderGroupHeader
      ? getPlannedGroupHeadersByItemIndex(plannedChunk?.groupHeaders)
      : undefined;

    return visibleIndexes.map((itemIndex) => {
      const item = items[itemIndex];
      if (item === undefined) return null;
      const key = getKey(item, itemIndex);
      const group = itemGroups[itemIndex];
      const fragmentIndex = fragmentPositions.get(itemIndex) ?? -1;
      const sourceTrackPosition = sourceTrackPositions?.get(itemIndex) ?? -1;
      const coreFragment = getFlowFragmentState({
        itemIndex,
        fragmentIndexes: visibleIndexes,
        fragmentIndex,
        groupKeys,
        pageIndex,
        pageCount,
        itemCount: items.length,
        previousSourceIndex: plannedChunk?.previousSourceIndex ?? (
          sourceTrackPosition > 0 ? sourceTrackIndexes?.[sourceTrackPosition - 1] : undefined
        ),
      });
      const fragment: StaticFlowFragmentContext<TItem> = {
        ...coreFragment,
        flowId: id,
        itemKey: key,
        item,
      };
      const type = resolveItemType?.(item, itemIndex) ?? (getItemType(item) as TType | undefined);
      const meta = mergeItemMeta(
        type ? metaDefaults?.[type] : undefined,
        getItemMeta?.(item, itemIndex)
      );
      const resolvedItemClassName =
        typeof itemClassName === 'function'
          ? itemClassName(item, itemIndex)
          : itemClassName;
      const containerProps = resolveContainerProps?.(itemIndex);
      const hasPlannedGroupHeader = Boolean(
        group && plannedGroupHeaders?.get(itemIndex)?.has(group.key)
      );
      const shouldRenderGroupHeader = Boolean(
        group &&
        renderGroupHeader &&
        (
          hasPlannedGroupHeader || (
            !plannedGroupHeaders &&
            fragment.isFirstInGroupOnPage &&
            (fragment.isFirstInGroup || group.repeatHeader !== false)
          )
        )
      );
      const resolvedGroupHeaderClassName: string | undefined =
        typeof groupHeaderClassName === 'function'
          ? (group ? groupHeaderClassName(group, fragment) : undefined)
          : groupHeaderClassName;

      return (
        <React.Fragment key={key}>
          {shouldRenderGroupHeader && group && (
            <div
              className={resolvedGroupHeaderClassName}
              style={{ display: 'flow-root' }}
              data-uhuu-flow-group-header="true"
              data-uhuu-flow-header-group-key={group.key}
            >
              {renderGroupHeader?.(group, fragment)}
            </div>
          )}
          <div
            className={[resolvedItemClassName, containerProps?.className].filter(Boolean).join(' ')}
            style={{ display: 'flow-root', ...containerProps?.style }}
            data-uhuu-flow-item="true"
            data-uhuu-flow-layout-node={markAsLayoutNode ? 'item' : undefined}
            data-uhuu-flow-key={String(key)}
            data-uhuu-flow-index={itemIndex}
            data-uhuu-flow-break-before={meta.breakBefore ? 'true' : undefined}
            data-uhuu-flow-break-after={meta.breakAfter ? 'true' : undefined}
            data-uhuu-flow-keep-with-next={serializeKeepWithNext(meta.keepWithNext)}
            data-uhuu-flow-avoid-break-inside={meta.avoidBreakInside ? 'true' : undefined}
            data-uhuu-flow-group-key={meta.groupKey}
            data-uhuu-flow-header-group-key={group?.key}
            data-uhuu-flow-header-repeat={
              group ? (group.repeatHeader === false ? 'false' : 'true') : undefined
            }
          >
            {renderItem(item, itemIndex, fragment)}
          </div>
        </React.Fragment>
      );
    });
  };

  const sourceColumnNodes = new Map(
    layout
      .filter((node): node is Extract<StaticFlowLayoutNode, { kind: 'columns' }> => (
        node.kind === 'columns'
      ))
      .map((node) => [node.id, node])
  );
  const renderedLayout = isMeasurement
    ? layout
    : (activeChunk?.layout ?? []);

  return (
    <div
      className={className}
      data-uhuu-flow="true"
      data-uhuu-flow-id={id}
      data-uhuu-flow-layout="columns"
    >
      {renderedLayout.map((entry, layoutIndex) => {
        if (entry.kind === 'item') {
          return (
            <React.Fragment key={`item:${entry.index}:${layoutIndex}`}>
              {renderIndexes([entry.index], undefined, undefined, true)}
            </React.Fragment>
          );
        }
        if (entry.kind === 'items') {
          return (
            <React.Fragment key={`items:${layoutIndex}`}>
              {renderUnplaceable(entry.chunk.unplaceable)}
              {renderIndexes(entry.chunk.indexes, entry.chunk, undefined, true)}
            </React.Fragment>
          );
        }

        const sourceNode = isMeasurement
          ? (entry as Extract<StaticFlowLayoutNode, { kind: 'columns' }>)
          : sourceColumnNodes.get(entry.id);
        if (!sourceNode) return null;
        const sourceColumnsById = new Map(sourceNode.columns.map((column) => [column.id, column]));
        const renderedColumns: Array<{ id: string; chunk?: StaticFlowChunk }> = isMeasurement
          ? sourceNode.columns.map((column) => ({ id: column.id }))
          : (entry as Extract<StaticFlowLayoutFragment, { kind: 'columns' }>).columns;
        const groupProps = getColumnGroupProps?.(sourceNode, columnsContext);

        return (
          <div
            key={`columns:${sourceNode.id}:${layoutIndex}`}
            className={groupProps?.className}
            style={{
              display: 'flex',
              width: '100%',
              alignItems: 'flex-start',
              ...groupProps?.style,
            }}
            data-uhuu-flow-layout-node="columns"
            data-uhuu-flow-layout-id={sourceNode.id}
          >
            {renderedColumns.map((renderedColumn) => {
              const sourceColumn = sourceColumnsById.get(renderedColumn.id);
              if (!sourceColumn) return null;
              const columnProps = getColumnProps?.(sourceNode, sourceColumn, columnsContext);
              const columnIndexes = renderedColumn.chunk?.indexes ?? sourceColumn.indexes;

              return (
                <div
                  key={sourceColumn.id}
                  className={columnProps?.className}
                  style={{
                    minWidth: 0,
                    flex: '1 1 0%',
                    display: 'flex',
                    flexDirection: 'column',
                    ...columnProps?.style,
                  }}
                  data-uhuu-flow-column={sourceColumn.id}
                >
                  {renderUnplaceable(renderedColumn.chunk?.unplaceable)}
                  {renderIndexes(
                    columnIndexes,
                    renderedColumn.chunk,
                    (itemIndex) => getColumnItemProps?.(
                      sourceNode,
                      sourceColumn,
                      itemIndex,
                      columnsContext
                    ),
                    false,
                    sourceColumn.indexes
                  )}
                </div>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}
